struct OwnedTrackerEndpoint::Impl {
  std::shared_ptr<const storage::ProfileLease> lease;fs::path profile;std::uint64_t session=0;std::thread::id worker;std::weak_ptr<Box> network;
  Policy expected;TrackerEndpointDescription description;std::atomic<bool> active{false};
};
OwnedTrackerEndpoint::OwnedTrackerEndpoint(std::shared_ptr<Impl> value)noexcept:impl_(std::move(value)){}
OwnedTrackerEndpoint::OwnedTrackerEndpoint(OwnedTrackerEndpoint&&)noexcept=default;OwnedTrackerEndpoint& OwnedTrackerEndpoint::operator=(OwnedTrackerEndpoint&&)noexcept=default;OwnedTrackerEndpoint::~OwnedTrackerEndpoint()=default;
const TrackerEndpointDescription& OwnedTrackerEndpoint::description()const noexcept{return impl_->description;}
std::expected<std::uint64_t,Error> OwnedTrackerEndpoint::current(const storage::ProfileLease& lease,std::uint64_t session)const{
  const bool lineage=impl_&&impl_->worker==std::this_thread::get_id()&&impl_->lease&&session==impl_->session&&lease.sharesOwnership(*impl_->lease);
  try{const auto network=impl_?impl_->network.lock():nullptr;require(lineage&&impl_->active&&network&&!network->stopping&&!network->exited&&profile(lease,impl_->profile),Code::Conflict,"Owned tracker endpoint is no longer current");auto gate=take(lease.sourceAccess());require(gate.observationsAllowed()&&policy(lease,true)==impl_->expected,Code::Conflict,"Owned tracker endpoint settings changed");return gate.revision();}
  catch(const Failure& e){if(lineage){impl_->active=false;if(const auto network=impl_->network.lock()){network->stopping=true;}}return std::unexpected(e.error);}
  catch(...){if(lineage){impl_->active=false;if(const auto network=impl_->network.lock()){network->stopping=true;}}return std::unexpected(Error{Code::Io,"Cannot validate owned tracker endpoint"});}
}
std::expected<OwnedTrackerEndpoint,Error> OwnedTrackerEndpoint::retainedCopy(const storage::ProfileLease& lease,std::uint64_t session)const{auto valid=current(lease,session);if(!valid){return std::unexpected(valid.error());}return OwnedTrackerEndpoint(impl_);}
